  "sim.progress.welcomeBack": "🔄 Chào mừng trở lại! Tiến độ của bạn đã được khôi phục — Điểm: {score}",
  "sim.progress.alreadyCompleted": "🔄 Chào mừng trở lại! Bạn đã hoàn thành mô phỏng này rồi.",
  "sim.egg-incubator.title": "Lò ấp trứng",
  "sim.egg-incubator.desc": "Quản lý nhiệt độ, độ ẩm và xoay trứng trong trại ấp để tối đa hóa tỷ lệ nở.",
  "sim.dairy-farm.title": "Trang trại sữa",
  "sim.dairy-farm.desc": "Vận hành trang trại sữa quy mô nhỏ: lịch cho ăn, chu kỳ vắt sữa và sức khỏe đàn để tối đa hóa sản lượng.",
  "sim.poultry-farm.title": "Trang trại gia cầm",
  "sim.poultry-farm.desc": "Quản lý trang trại gia cầm thương mại — thức ăn, sức khỏe và mục tiêu sản xuất cho đàn gà thịt và gà đẻ.",
  "sim.cattle-dairy.title": "Chăn nuôi bò & Trang trại sữa",
  "sim.cattle-dairy.desc": "Quản lý trang trại chăn bò và đơn vị sữa, cân bằng giữa quản lý đồng cỏ, lai giống và sản xuất sữa.",
  "sim.sheep-farm.title": "Trang trại cừu",
  "sim.sheep-farm.desc": "Vận hành trang trại cừu theo các chu kỳ mùa vụ: sinh cừu con, cắt lông và bán hàng ra thị trường.",
  "sim.network-noc.title": "Network NOC",
  "sim.network-noc.desc": "Đóng vai kỹ sư Trung tâm Vận hành Mạng — chẩn đoán và xử lý sự cố hạ tầng trực tiếp trong áp lực cao.",
  "sim.mobile-repair.title": "Xưởng sửa chữa di động",
  "sim.mobile-repair.desc": "Chẩn đoán và sửa điện thoại thông minh — thay màn hình, lỗi pin và sự cố bo mạch chủ.",
  "sim.laptop-repair.title": "Xưởng sửa chữa laptop",
  "sim.laptop-repair.desc": "Khắc phục và sửa laptop: lỗi phần cứng, lỗi BIOS và thay thế linh kiện.",
  "sim.perfume-lab.title": "Phòng thí nghiệm nước hoa",
  "sim.perfume-lab.desc": "Trộn tinh dầu và hợp chất tạo mùi để tạo hương đặc trưng và đạt chuẩn chất lượng.",
  "sim.detergent-lab.title": "Phòng thí nghiệm bột giặt",
  "sim.detergent-lab.desc": "Pha chế sản phẩm vệ sinh — cân bằng chất hoạt động bề mặt, chất độn và thử nghiệm hiệu năng trong ngân sách.",
  "sim.skin-care-lab.title": "Phòng thí nghiệm chăm sóc da",
  "sim.skin-care-lab.desc": "Phát triển và thử nghiệm công thức mỹ phẩm, đáp ứng tiêu chuẩn an toàn và mục tiêu hiệu quả.",
  "sim.woodworking.title": "Xưởng làm đồ gỗ",
  "sim.woodworking.desc": "Vận hành xưởng làm đồ gỗ theo yêu cầu: lên kế hoạch việc làm, quản lý vật liệu và giao đồ nội thất đúng tiến độ và đúng ngân sách.",
  "sim.aluminum-glazing.title": "Nhôm & Lắp kính",
  "sim.aluminum-glazing.desc": "Quản lý doanh nghiệp gia công nhôm và lắp đặt kính từ báo giá đến hoàn thiện công trình.",
  "sim.global-kitchen.title": "Bếp toàn cầu",
  "sim.global-kitchen.desc": "Dẫn dắt bếp nhà hàng: quản lý thực đơn, nhân sự, chi phí và mức độ hài lòng của khách trong các ca phục vụ.",
  "sim.chocolate-factory.title": "Nhà máy sô-cô-la",
  "sim.chocolate-factory.desc": "Vận hành nhà máy thực phẩm kẹo — tìm nguồn cacao, lập lịch sản xuất và kiểm soát chất lượng.",
  "sim.solar-energy.title": "Nhà máy điện năng lượng mặt trời",
  "sim.solar-energy.desc": "Thiết kế và vận hành hệ thống điện mặt trời — tính kích thước tấm, quản lý xuất điện lên lưới và theo dõi ROI.",
  "sim.hvac-systems.title": "Hệ thống HVAC",
  "sim.hvac-systems.desc": "Lắp đặt và bảo trì hệ thống sưởi, thông gió và điều hòa không khí cho các tòa nhà thương mại.",
  "sim.logistics-supply.title": "Vận tải & Chuỗi cung ứng",
  "sim.logistics-supply.desc": "Tối ưu hóa vận hành kho, lập tuyến đội xe và quan hệ với nhà cung cấp để đạt KPI giao hàng.",
  "sim.barber-salon.title": "Tiệm cắt tóc",
  "sim.barber-salon.desc": "Quản lý tiệm cắt tóc: đặt lịch, lịch làm việc nhân sự, giá cả và chiến lược giữ chân khách hàng.",
  "sim.board-surgeon.title": "Bác sĩ phẫu thuật tuyến đầu",
  "sim.board-surgeon.desc": "Ra quyết định phẫu thuật đầy rủi ro trong phòng mổ mô phỏng — quản lý thời gian và đảm bảo an toàn cho bệnh nhân.",
  "sim.english-journey.title": "Hành trình tiếng Anh",
