  "neonbreach.howTo.3": "Mỗi mức đúng sẽ thêm một ô nữa để ghi nhớ",
  "neonbreach.howTo.4": "Chỉ cần chạm sai một lần là tường lửa sẽ bắt được bạn!",
  "earmaster.howTo.1": "Lắng nghe kỹ nốt nhạc đang được phát",
  "earmaster.howTo.2": "Chọn nốt bạn đã nghe trong 7 lựa chọn",
  "earmaster.howTo.3": "Dùng nút Phát để nghe lại nốt một lần",
  "earmaster.howTo.4": "Hoàn tất 10 vòng để xem điểm cuối cùng",
  "uno.howTo.1": "Ghép lá bài trên cùng của chồng theo màu hoặc số",
  "uno.howTo.2": "Chạm vào một lá bài trong tay để đánh",
  "uno.howTo.3": "Nếu không có lá khớp, hãy chạm Vẽ để rút thêm một lá",
  "uno.howTo.4": "Ai làm hết bài trên tay trước sẽ thắng!",
  "briscola.howTo.1": "Briscola là trò chơi bài kiểu “đánh ăn” của Ý",
  "briscola.howTo.2": "Chất át (Briscola) thắng tất cả các chất còn lại",
  "briscola.howTo.3": "Thắng lượt để kiếm điểm — Át=11, 3=10, King=4, Queen=3, Jack=2",
  "briscola.howTo.4": "Tổng điểm cao nhất sau khi đánh hết các lá sẽ thắng",
  "card99.howTo.1": "Đánh bài để giữ tổng chạy luôn ở mức 99 hoặc thấp hơn",
  "card99.howTo.2": "Lá đặc biệt: King=0, Queen=giữ, Jack=−10, Át=1 hoặc 11",
  "card99.howTo.3": "Vượt tổng quá 99 là bạn mất một mạng",
  "card99.howTo.4": "Người còn lại cuối cùng với số mạng còn lại sẽ thắng!",
  "dominoes.howTo.1": "Ghép các con số ở hai đầu của chuỗi domino",
  "dominoes.howTo.2": "Đánh các quân từ tay khớp với một đầu đang mở",
  "dominoes.howTo.3": "Nếu không thể đánh, hãy rút từ chồng",
  "dominoes.howTo.4": "Ai làm hết bài trên tay trước (hoặc tổng pip thấp nhất) sẽ thắng!",
  "farkle.howTo.1": "Lăn 6 xúc xắc và gạt riêng mọi xúc xắc có ghi điểm",
  "farkle.howTo.2": "1 = 100 điểm · 5 = 50 điểm · Sét 3 con giống nhau = mặt × 100",
  "farkle.howTo.3": "Nếu KHÔNG có xúc xắc nào ghi điểm trong lượt, đó là FARKLE — mất lượt!",
  "farkle.howTo.4": "Gom điểm lại để giữ lấy, hoặc lăn tiếp để nhận thêm rủi ro/phần thưởng",
  "quiz.howTo.1": "Trả lời 20 câu hỏi trắc nghiệm nhanh nhất có thể",
  "quiz.howTo.2": "Mỗi câu có 3 giây — trả lời thật nhanh!",
  "quiz.howTo.3": "Trả lời đúng nhanh hơn sẽ nhận được nhiều điểm thưởng hơn",
  "quiz.howTo.4": "Hoàn tất tất cả câu hỏi để xem hạng cuối cùng của bạn",
  "memory.howTo.1": "Lật 2 thẻ cùng lúc để tìm các cặp khớp",
  "memory.howTo.2": "Nếu khớp, chúng sẽ được giữ nguyên úp mặt",
  "memory.howTo.3": "Nếu không, cả hai sẽ lật lại úp xuống — nhớ vị trí của chúng!",
  "memory.howTo.4": "Ghép tất cả các cặp với ít lượt di chuyển nhất có thể để đạt điểm cao",
  "word.howTo.1": "Xáo trộn các chữ cái để tạo thành từ bị ẩn",
  "word.howTo.2": "Chạm các chữ theo đúng thứ tự để tạo câu trả lời của bạn",
  "word.howTo.3": "Dùng nút Gợi ý nếu bạn bị kẹt (tốn điểm)",
  "word.howTo.4": "Hoàn thành 8 từ để kết thúc câu đố",
  "hangman.howTo.1": "Đoán từ bị ẩn từng chữ một",
